enum ScriptDirection { ltr, rtl }

class IsoScriptProfile {
  final String code;
  final ScriptDirection direction;
  final bool requiresComplexShaping;
  final bool toneMarked;

  const IsoScriptProfile({
    required this.code,
    required this.direction,
    this.requiresComplexShaping = false,
    this.toneMarked = false,
  });

  bool get isRtl => direction == ScriptDirection.rtl;
}

enum LanguageReadiness {
  registered,
  sourceApproved,
  productionReady,
}

class LanguageCapabilities {
  final bool hasOfflineTts;
  final bool hasGrammarEngine;
  final bool hasLemmatization;
  final bool hasFts5;

  const LanguageCapabilities({
    this.hasOfflineTts = false,
    this.hasGrammarEngine = false,
    this.hasLemmatization = false,
    this.hasFts5 = false,
  });
}

class CanonicalLanguageProfile {
  final String bcp47;
  final String nativeName;
  final String nameAr;
  final String flag;
  final IsoScriptProfile script;
  final LanguageReadiness readiness;
  final LanguageCapabilities capabilities;

  const CanonicalLanguageProfile({
    required this.bcp47,
    required this.nativeName,
    required this.nameAr,
    required this.flag,
    required this.script,
    this.readiness = LanguageReadiness.registered,
    this.capabilities = const LanguageCapabilities(),
  });

  bool get isRtl => script.isRtl;
  bool get isProductionReady => readiness == LanguageReadiness.productionReady;
}

