  static CanonicalLanguageProfile? getProfile(String code) {
    return catalog[code.trim().toLowerCase()];
  }

  static bool isSupported(String code) {
    return catalog.containsKey(code.trim().toLowerCase());
  }

  static List<CanonicalLanguageProfile> getAllProfiles() {
    return catalog.values.toList();
  }

  static List<CanonicalLanguageProfile> getRtlProfiles() {
    return catalog.values.where((p) => p.isRtl).toList();
  }

  static int get totalCount => catalog.length;
}

class DirectedPairRegistry {
  static String? _activePairId;

  static void setActivePair(String sourceLocale, String targetLocale) {
    if (!CanonicalLanguageCatalog.isSupported(sourceLocale) ||
        !CanonicalLanguageCatalog.isSupported(targetLocale)) {
      throw ArgumentError('Unsupported language in pair ($sourceLocale -> $targetLocale)');
    }
    if (sourceLocale.toLowerCase() == targetLocale.toLowerCase()) {
      throw ArgumentError('Reflexive pairs are not permitted ($sourceLocale -> $targetLocale)');
    }
    _activePairId = '${sourceLocale.toLowerCase()}_${targetLocale.toLowerCase()}';
  }

  static String? get activePairId => _activePairId;

  static void clearActivePair() {
    _activePairId = null;
  }
}
